"""Owner-only prospective forecast baselines, never a replacement agent forecast.

These baselines forecast the agent's requested actions using its committed public
evidence cutoff. They do not choose experiments and are not training controls or
evidence of an agent advantage. No private response world is an input.
"""

from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path

from .contracts import ConflictError, ContractError, canonical, digest
from .investigation.controller import validate_forecast
from .investigation.executor import IMAGE, execute
from .models import bootstrap_model_source, conventional_model_source, public_source_packet
from .private_paths import validate_private_path
from .store import now

ASSUMPTIONS = {
    "version": "owner-comparators-v1",
    "action_access": "same-request forecast only; no experiment acquisition or selection",
    "source_transfer": "explicit conditional transfer to the request lot/geometry, not calibration",
    "grain_prior": "unsupported absent resolved same-cutoff local evidence",
    "local_method": "local_linear_actual_temperature",
    "recipe_tolerances": {"pressure_mpa": 2.0},
    "local_rationale": "Declared local linear mean over actual delivered temperature; pressure "
    "within 2 MPa is treated as locally comparable. This is not an RPI acceptance limit.",
    "other_recipe_fields": "exact delivered ramp, hold and post-treatment matching",
    "extrapolation": "none outside source or local observed temperature support",
    "uncertainty": "no assumed source SD; local residual scatter only where independent IDs permit",
    "claims": "forecast baselines only; not matched training controls or agent-advantage evidence",
}


def _bytes(value):
    return (canonical(value) + "\n").encode()


def _sha(value):
    return hashlib.sha256(value).hexdigest()


def _write_new(path, content):
    with path.open("xb") as stream:
        stream.write(content)
        stream.flush()
        os.fsync(stream.fileno())
    path.chmod(0o444)


def _source(assimilate):
    # Strip agent analysis choices; only physical request conditions enter either baseline.
    # This wrapper is frozen as executable bytes alongside its declared assumptions.
    source = conventional_model_source() if assimilate else bootstrap_model_source()
    source = source.split('\nif __name__ == "__main__":', 1)[0]
    source = source.replace("def forecast(payload):", "def _baseline_forecast(payload):", 1)
    return (
        source
        + """

def forecast(payload):
    import copy
    request = copy.deepcopy(payload["request"])
    keys = ("route", "temperature_c", "pressure_mpa", "hold_time_s",
            "heating_rate_c_min", "mass_g", "diameter_mm", "post_treatment",
            "process_stage", "measurement_population", "measurement_statistic", "die_material")
    for specimen in request["specimens"]:
        original = specimen["conditions"]
        condition = {key: original[key] for key in keys if key in original}
        condition["route"] = specimen.get("material_route") or condition["route"]
        condition["lot_id"] = request["lot_id"]
        condition["allow_source_transfer"] = True
        condition["evidence_origin"] = request["origin"]
        condition["empirical_method"] = "local_linear_actual_temperature"
        condition["empirical_assumption_rationale"] = __RATIONALE__
        condition["evidence_recipe_tolerances"] = {"pressure_mpa": 2.0}
        specimen["conditions"] = condition
    return _baseline_forecast({"request": request, "evidence": payload["evidence"],
                               "investigation_state": {}, "sources": payload["sources"]})
""".replace("__RATIONALE__", repr(ASSUMPTIONS["local_rationale"]))
    )


def _as_of_evidence(campaign, request):
    ids = request["evidence_ids"]
    if len(ids) != len(set(ids)):
        raise ContractError("committed evidence IDs are not unique")
    current = {row["evidence_id"]: row for row in campaign.evidence()}
    if any(identifier not in current for identifier in ids):
        raise ContractError("committed evidence is missing from immutable release history")
    selected = [current[identifier] for identifier in ids]
    # The current view includes later correction flags. Only corrections already in
    # the committed ID set may supersede an observation at this historical cutoff.
    superseded = {
        row["corrects_delivery_id"] for row in selected if row.get("corrects_delivery_id")
    }
    selected = [{**row, "superseded": row["delivery_id"] in superseded} for row in selected]
    if any(row["released_at"] > request["committed_at"] for row in selected):
        raise ContractError("committed evidence contains a post-cutoff release")
    if digest(selected) != request["evidence_sha256"]:
        raise ContractError("reconstructed as-of evidence differs from committed evidence hash")
    return selected


def _read_existing(directory, request_hash):
    receipt_path = directory / "comparators.json"
    if not receipt_path.is_file() or receipt_path.is_symlink():
        raise ConflictError(
            "incomplete comparator snapshot; retain it and use a new output directory"
        )
    record = json.loads(receipt_path.read_text())
    if record.get("request_record_sha256") != request_hash:
        raise ConflictError("comparator snapshot binds a different committed request")
    for relative, expected in record["artifact_sha256"].items():
        path = directory / relative
        if (
            Path(relative).is_absolute()
            or ".." in Path(relative).parts
            or path.is_symlink()
            or not path.is_file()
            or _sha(path.read_bytes()) != expected
        ):
            raise ContractError("immutable comparator artifact integrity check failed")
    names = {"source_only_prior", "local_actual_temperature"}
    if set(record.get("comparators", {})) != names:
        raise ContractError("comparator summary has missing or unexpected baselines")
    for name in names:
        model = record["comparators"][name]
        prediction_path = f"{name}/prediction.json"
        source_path = f"{name}/workspace/model.py"
        if not {prediction_path, source_path} <= record["artifact_sha256"].keys():
            raise ContractError("comparator summary lacks required artifact bindings")
        prediction = json.loads((directory / prediction_path).read_text())
        if (
            canonical(model.get("prediction")) != canonical(prediction)
            or model.get("prediction_sha256") != digest(prediction)
            or model.get("source_sha256") != record["artifact_sha256"][source_path]
        ):
            raise ContractError(
                "comparator summary disagrees with hashed prediction/source artifacts"
            )
    return {**json.loads(canonical(record)), "artifact_directory": str(directory)}


def freeze_comparators(campaign, request_id: str, output_dir: str | Path) -> dict:
    """Freeze two owner-only baselines at a request's original evidence cutoff.

    Four real isolated Docker executions (two per model) are required on first
    success; existing snapshots are integrity-checked and returned without rerun.
    Later corrections cannot modify the saved inputs or supersession state.
    A newly saved snapshot after target delivery is labeled retrospective. The
    temporal claim is receipt-order only, not proof of physical execution timing.
    """
    request = campaign.request(request_id)
    request_hash = digest(request)
    root = Path(output_dir).expanduser()
    if any(p.is_symlink() for p in (root, *root.parents)):
        raise ContractError("comparator output must not traverse symlinks")
    root = root.resolve()
    validate_private_path(root, error_type=ContractError)
    root.mkdir(parents=True, exist_ok=True, mode=0o700)
    directory = root / ("request-" + request_hash[:24])
    if directory.exists():
        return _read_existing(directory, request_hash)
    with campaign.store.transaction():
        evidence = _as_of_evidence(campaign, request)
    directory.mkdir(mode=0o700)
    started_at = now()
    _write_new(directory / "request_record.json", _bytes(request))
    _write_new(directory / "assumptions.json", _bytes(ASSUMPTIONS))
    payload = {
        "request": request["request"],
        "evidence": evidence,
        "investigation_state": {},
        "sources": public_source_packet(),
    }
    _write_new(directory / "input.json", _bytes(payload))
    results = {}
    for name, assimilation in (("source_only_prior", False), ("local_actual_temperature", True)):
        model_dir = directory / name
        workspace = model_dir / "workspace"
        workspace.mkdir(parents=True, mode=0o755)
        source = _source(assimilation).encode()
        _write_new(workspace / "model.py", source)
        runs = [execute(workspace, payload, model_dir / "executions") for _ in range(2)]
        for run in runs:
            if run.get("status") != "ok":
                raise ContractError(
                    "comparator Docker execution failed; inspect retained private receipts"
                )
            if (
                run["container_restrictions"]["image"] != IMAGE
                or run["hashes"]["executed_source_sha256"] != _sha(source)
                or run["hashes"]["input_sha256"] != _sha(_bytes(payload))
            ):
                raise ContractError("comparator runtime/source/input binding mismatch")
            validate_forecast(run["result"], request["request"])
        if canonical(runs[0]["result"]) != canonical(runs[1]["result"]):
            raise ContractError("comparator forecast is not deterministic")
        _write_new(model_dir / "prediction.json", _bytes(runs[0]["result"]))
        results[name] = {
            "source_sha256": _sha(source),
            "prediction": runs[0]["result"],
            "prediction_sha256": digest(runs[0]["result"]),
            "execution_ids": [run["execution_id"] for run in runs],
            "image": IMAGE,
            "evidence_ids": request["evidence_ids"],
        }
    # Serialize final receipt creation against delivery commits. This does not
    # contact a lab or prevent external work; it only establishes receipt ordering.
    with campaign.store.transaction():
        target_deliveries = [
            d["delivery_id"]
            for d in campaign.store.all("delivery")
            if d["request_id"] == request_id
        ]
        record = {
            "schema_version": 1,
            "request_id": request_id,
            "request_record_sha256": request_hash,
            "agent_forecast_sha256": digest(request["prediction"]),
            "evidence_cutoff": request["committed_at"],
            "evidence_ids": request["evidence_ids"],
            "evidence_sha256": request["evidence_sha256"],
            "started_at": started_at,
            "saved_at": now(),
            "prospective": not target_deliveries,
            "timing_status": "saved_before_any_target_delivery_receipt"
            if not target_deliveries
            else "retrospective_saved_after_target_delivery_receipt",
            "target_deliveries_already_received": target_deliveries,
            "timing_limit": "Receipt ordering does not authenticate external physical execution time",
            "owner_only": True,
            "assumptions": ASSUMPTIONS,
            "comparators": results,
            "claim_scope": "same-request forecast baselines; no training or agent-advantage claim",
            "artifact_sha256": {
                str(p.relative_to(directory)): _sha(p.read_bytes())
                for p in sorted(directory.rglob("*"))
                if p.is_file()
            },
        }
        _write_new(directory / "comparators.json", _bytes(record))
    return {**json.loads(canonical(record)), "artifact_directory": str(directory)}
